// First Grasm program — exercises most Phase-1 lexemes.
pub fn main() {
    let name = "world"
    let xs = [1, 2, 3, 4, 5]
    var total = 0
    for x in xs {
        if x % 2 == 0 {
            total += x
        }
    }
    print("hello, {name}! even sum: {total}")
}

// Fallible functions demo.
type MathError = | DivByZero

fn safe_div(a: i64, b: i64) -> i64 ! MathError {
    if b == 0 {
        fail(DivByZero)
    }
    a / b
}

fn main() {
    match safe_div(10, 0) {
        Ok(v) -> print("{v}")
        Err(e) -> print("caught: {e}")
    }
}

test "division works" {
    let v = try safe_div(10, 2)
    assert_eq(v, 5)
}

// Effects demo: capability-style DI without frameworks.
effect Clock {
    fn now() -> i64
}

effect Greeter {
    fn greet(name: str) -> str
}

fn timestamped_hello(name: str, start: i64) -> str {
    let elapsed = Clock.now() - start
    Greeter.greet(name) + " (t+{elapsed})"
}

fn main() {
    with Clock handled_by ClockHandler{ now: || 1000 } {
        with Greeter handled_by GreeterHandler{ greet: |n| "hello, " + n } {
            print(timestamped_hello("world", 990))
        }
    }
}

test "handlers are swappable" {
    with Clock handled_by ClockHandler{ now: || 5 } {
        with Greeter handled_by GreeterHandler{ greet: |n| n.to_upper() } {
            assert_eq(timestamped_hello("ada", 0), "ADA (t+5)")
        }
    }
}

// Generic types: families of types, one member per use.
//
// `type Stack[T]` describes a family. A use fixes the parameter — a struct
// literal reads it off the fields it gives, a sum constructor off its arguments
// — and each member is its own type, so a `Stack[i64]` and a `Stack[str]` are
// two of them ([T-GENERIC-TYPE]).
type Stack[T] = { items: [T] }
type Pair[A, B] = { fst: A, snd: B }
type Opt[T] = | Has(v: T) | Nix
type Tree[T] = | Leaf | Node(left: Tree[T], value: T, right: Tree[T])

fn push[T](s: Stack[T], v: T) -> Stack[T] {
    var xs = s.items
    xs.push(v)
    Stack{ items: xs }
}

fn firsts[A, B](ps: [Pair[A, B]]) -> [A] {
    ps.map(|p| p.fst)
}

fn get_or[T](o: Opt[T], d: T) -> T {
    match o {
        Has(v) -> v
        Nix -> d
    }
}

// A generic type may mention itself. The name is registered before its fields
// are resolved, so this describes a tree rather than recursing forever.
fn depth[T](t: Tree[T]) -> i64 {
    match t {
        Leaf -> 0
        Node(l, v, r) -> {
            let a = depth(l)
            let b = depth(r)
            if a > b { a + 1 } else { b + 1 }
        }
    }
}

fn main() {
    var s = Stack{ items: [1] }
    s = push(s, 2)
    print("{push(s, 3).items}")

    // The same function, a different member of the family.
    let words: Stack[str] = Stack{ items: ["a"] }
    print("{push(words, "b").items}")

    let ps = [Pair{ fst: 1, snd: "a" }, Pair{ fst: 2, snd: "b" }]
    print("{firsts(ps)}")

    // Two instantiations of one sum in one program, which is the case that
    // has to work: `Has(5)` and `Has("s")` are an `Opt[i64]` and an `Opt[str]`.
    print("{get_or(Has(5), 0)} {get_or(Nix, 9)}")
    print("{get_or(Has("s"), "d")}")

    let t: Tree[i64] = Node(Node(Leaf, 1, Leaf), 2, Leaf)
    print("{depth(t)}")
}

test "a family's members are separate types" {
    assert_eq(get_or(Has(5), 0), 5)
    assert_eq(get_or(Has("s"), "d"), "s")
    assert_eq(push(Stack{ items: [1] }, 2).items.len(), 2)
}

test "a generic type may mention itself" {
    let t: Tree[str] = Node(Leaf, "root", Node(Leaf, "r", Leaf))
    assert_eq(depth(t), 2)
}

// Functions as data — and every line here compiles natively as well as
// running in the interpreter, which is the point.
//
//   grasm run   examples/function_values.gr
//   grasm build examples/function_values.gr --native -o fv && ./fv
//
// A named function and a closure share one representation: a code pointer
// plus a captured environment. That is why a list can hold either, and why
// calling one is the same indirect call in both cases.

fn inc(n: i64) -> i64 {
    n + 1
}

fn double(n: i64) -> i64 {
    n * 2
}

fn square(n: i64) -> i64 {
    n * n
}

/// Applies every function in `pipeline` to `seed`, in order.
fn run_pipeline(seed: i64, stages: [i64]) -> i64 {
    var acc = seed
    for s in stages {
        acc = acc + s
    }
    acc
}

fn main() {
    // A named function bound to a variable, then called through it.
    let f = inc
    print("{f(41)}")

    // Functions in a list, iterated and called indirectly.
    let stages = [inc, double, square]
    var acc = 3
    for stage in stages {
        acc = stage(acc)
    }
    print("3 -> {acc}")

    // A closure bound to a name.
    let halve = |n| n / 2
    print("{halve(84)}")

    // Closures capture by value at the moment they are created, so a later
    // change to the captured binding is not visible inside.
    var offset = 10
    let shift = |n| n + offset
    offset = 1000
    print("{shift(5)} offset={offset}")

    // Captures may be boxed values, and outlive the scope they came from.
    let label = "result"
    let describe = |n| "{label}: {n}"
    print(describe(7))

    // Printing a function value says which one it is.
    print("{f}")
    print("{halve}")

    let totals = [1, 2, 3]
    print("{run_pipeline(0, totals)}")

    // A named function passed to a combinator, which is the way most people
    // reach for first. The backend used to require a closure written at the
    // call site and refuse this, so `xs.map(square)` compiled only under the
    // interpreter.
    let ns = [1, 2, 3, 4, 5]
    print("{ns.map(square)}")
    print("{ns.filter(is_even)}")
    print("{ns.any(is_even)} {ns.all(is_even)}")
    print("{ns.find(is_even) ?? -1}")
    print("{ns.par_map(square)}")
    print("{ns.par_filter(is_even)}")
    print("{mixed()}")
}

fn is_even(n: i64) -> bool {
    n % 2 == 0
}

/// A list holding a named function and a closure together.
///
/// The annotation is doing real work: nothing in `|n| n + 100` says what `n`
/// is, and inside a list there is no call site to learn it from. Naming the
/// element type once is what makes both spellings usable in one place.
fn mixed() -> i64 {
    let fs: [fn(i64) -> i64] = [double, |n| n + 100]
    var total = 0
    for f in fs {
        total = total + f(1)
    }
    total
}

// Combinators the standard library does not provide, written in the language.
//
//   grasm run   examples/combinators.gr
//   grasm build examples/combinators.gr --native -o comb && ./comb
//
// None of this was expressible before `fn(A, B) -> R` became a type you can
// write. A program could use the built-in `map` and `filter` and could not
// declare anything of that shape itself, which is why a missing `fold` was a
// hole rather than an inconvenience.
//
// Every function parameter below states the empty effect row by saying
// nothing, so passing something that prints is an error at the call site.

/// Left fold. The one the library is most often asked for.
fn fold(xs: [i64], init: i64, f: fn(i64, i64) -> i64) -> i64 {
    var acc = init
    for x in xs {
        acc = f(acc, x)
    }
    acc
}

/// `g` after `f`.
fn compose(f: fn(i64) -> i64, g: fn(i64) -> i64, x: i64) -> i64 {
    g(f(x))
}

/// How many elements satisfy a predicate.
fn count_where(xs: [i64], pred: fn(i64) -> bool) -> i64 {
    var n = 0
    for x in xs {
        if pred(x) {
            n = n + 1
        }
    }
    n
}

/// Applies `f` until it stops changing the value, or `limit` runs out.
fn fixpoint(f: fn(i64) -> i64, start: i64, limit: i64) -> i64 {
    var cur = start
    for _step in 0..limit {
        let next = f(cur)
        if next == cur {
            return cur
        }
        cur = next
    }
    cur
}

fn add(a: i64, b: i64) -> i64 {
    a + b
}

fn largest(a: i64, b: i64) -> i64 {
    if a > b { a } else { b }
}

fn inc(n: i64) -> i64 {
    n + 1
}

fn dbl(n: i64) -> i64 {
    n * 2
}

fn halve_toward_zero(n: i64) -> i64 {
    n / 2
}

fn main() {
    let xs = [3, 1, 4, 1, 5, 9, 2, 6]

    // A named function passed as a value.
    print("{fold(xs, 0, add)}")
    print("{fold(xs, 0, largest)}")

    // A closure, whose parameter types come from the parameter it fills.
    print("{fold(xs, 1, |a, b| a * b)}")

    print("{compose(inc, dbl, 5)}")
    print("{compose(dbl, inc, 5)}")

    print("{count_where(xs, |x| x % 2 == 0)}")
    print("{count_where(xs, |x| x > 3)}")

    // Halving reaches zero and stays there.
    print("{fixpoint(halve_toward_zero, 1000, 64)}")

    // The built-in combinators take the same values.
    print("{xs.map(dbl)}")
    print("{xs.filter(|x| x > 3)}")
}

// A range is a value, and `range` is its type.
//
// `let r = 0..n` binds one; it holds three numbers rather than its elements,
// so `0..2_000_000` costs the same as `0..2` ([L-LIB-RANGE-OPS]). What was
// missing was the *name*: `Type::Range` had displayed as `range` in error
// messages since ranges became values, and nothing parsed it. So a range could
// be bound and never declared — not a parameter, not a result, not a field —
// and a value you can hold and cannot pass is stuck inside one function body.
type Window = { span: range, label: str }

fn window(start: i64, count: i64) -> range {
    start..start + count
}

fn total(r: range) -> i64 {
    r.sum()
}

// A range reaches a method by more shapes than a name. Each of these was
// refused while `let r = 0..3` first compiled, because the test for "does this
// hold a range" only recognised a bare name.
fn main() {
    let r = window(1, 3)
    print("{r} {r.len()} {total(r)}")

    let w = Window{ span: 0..3, label: "first" }
    print("{w.label} {w.span} {w.span.to_list()}")

    // An element of a list.
    let rs: [range] = [0..2, 5..9]
    print("{rs[1].len()} {rs[0].map(|v| v * 10)}")

    // A closure's result.
    let f = || 2..6
    print("{f().len()} {f().sum()}")

    // A function's result, straight into a method.
    print("{window(10, 4).filter(|v| v > 11)}")

    // And walked, from a shape that is not a name.
    var seen = 0
    for i in rs[0] {
        seen = seen + i
    }
    print("{seen}")

    // A range's list surface answers a *list*, so a chain leaves the range
    // behind after the first call. Typing `filter` as the receiver's own type
    // made the backend believe this still held one, and it aborted inside
    // `range_to_list` on the list it was handed.
    print("{(0..6).map(|v| v * 3).filter(|v| v > 4)}")
    print("{rs[0].map(|v| v + 1).sum()} {window(1, 4).to_list()}")

    // Two ranges compare by their bounds and their inclusiveness.
    print("{0..3 == 0..3} {0..3 == 0..=3}")
}

// Tier-0 ownership: own transfers, inout mutates in place, default copies.
fn consume(own secret: str) -> i64 {
    secret.len()
}

fn bump(inout counter: i64) {
    counter += 1
}

fn main() {
    // own: the value is gone after transfer (uncomment to see the error)
    let token = "abc123"
    let n = consume(token)
    // print(token)   // error: use of moved value `token`

    // inout: caller sees the mutation
    var hits = 0
    bump(hits)
    bump(hits)
    print("len={n} hits={hits}")
}
